dashboard.definition:
{
    "title": "Overview",
    "description": "Is all expected data arriving? This page shows which hosts need attention and why, recent recoveries and tamper findings. It refreshes every minute. Click a row to open Host detail.",
    "inputs": {
        "input_site": {
            "type": "input.dropdown",
            "title": "Site",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "f_site",
                "defaultValue": "*"
            },
            "dataSources": {
                "primary": "ds_opt_site"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [
                    [
                        "All"
                    ],
                    [
                        "*"
                    ]
                ],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_owner": {
            "type": "input.dropdown",
            "title": "Owner",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "f_owner",
                "defaultValue": "*"
            },
            "dataSources": {
                "primary": "ds_opt_owner"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [
                    [
                        "All"
                    ],
                    [
                        "*"
                    ]
                ],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_index": {
            "type": "input.dropdown",
            "title": "Index",
            "options": {
                "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
                "token": "f_index",
                "defaultValue": "*"
            },
            "dataSources": {
                "primary": "ds_opt_index"
            },
            "context": {
                "formattedConfig": {
                    "number": {
                        "prefix": ""
                    }
                },
                "formattedStatics": ">statics | formatByType(formattedConfig)",
                "statics": [
                    [
                        "All"
                    ],
                    [
                        "*"
                    ]
                ],
                "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
                "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
            }
        },
        "input_crit": {
            "type": "input.dropdown",
            "title": "Criticality",
            "options": {
                "items": [
                    {
                        "label": "All",
                        "value": "*"
                    },
                    {
                        "label": "1 (highest)",
                        "value": "1"
                    },
                    {
                        "label": "2",
                        "value": "2"
                    },
                    {
                        "label": "3",
                        "value": "3"
                    },
                    {
                        "label": "4",
                        "value": "4"
                    }
                ],
                "token": "f_crit",
                "defaultValue": "*"
            }
        },
        "input_status": {
            "type": "input.dropdown",
            "title": "Status",
            "options": {
                "items": [
                    {
                        "label": "All",
                        "value": "*"
                    },
                    {
                        "label": "Host DOWN",
                        "value": "DOWN"
                    },
                    {
                        "label": "Host DEGRADED",
                        "value": "DEGRADED"
                    },
                    {
                        "label": "MISSING",
                        "value": "MISSING"
                    },
                    {
                        "label": "NEVER_SEEN",
                        "value": "NEVER_SEEN"
                    },
                    {
                        "label": "LATE",
                        "value": "LATE"
                    },
                    {
                        "label": "OK",
                        "value": "OK"
                    },
                    {
                        "label": "MUTED",
                        "value": "MUTED"
                    },
                    {
                        "label": "PENDING",
                        "value": "PENDING"
                    },
                    {
                        "label": "INFO",
                        "value": "INFO"
                    }
                ],
                "token": "f_status",
                "defaultValue": "*"
            }
        },
        "input_text": {
            "type": "input.text",
            "title": "Search text (words separated by *)",
            "options": {
                "token": "f_text",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "-24h@h",
                        "latest": "now"
                    },
                    "refresh": "60s",
                    "refreshType": "delay"
                }
            }
        }
    },
    "dataSources": {
        "ds_all": {
            "type": "ds.search",
            "name": "Current dh_status rows",
            "options": {
                "query": "| `dh_ui_status(dh_status)`"
            }
        },
        "ds_kpi": {
            "type": "ds.chain",
            "name": "KPIs per level (filtered)",
            "options": {
                "extend": "ds_all",
                "query": "| eval f_site=$f_site|s$, f_owner=$f_owner|s$, f_index=$f_index|s$, f_crit=$f_crit|s$, f_status=$f_status|s$, f_text=$f_text|s$ | `dh_ui_filter` | `dh_ui_kpi`"
            }
        },
        "ds_headline": {
            "type": "ds.chain",
            "name": "Needs attention headline (filtered)",
            "options": {
                "extend": "ds_all",
                "query": "| eval f_site=$f_site|s$, f_owner=$f_owner|s$, f_index=$f_index|s$, f_crit=$f_crit|s$, f_status=$f_status|s$, f_text=$f_text|s$ | `dh_ui_filter` | `dh_ui_attention_headline`"
            }
        },
        "ds_attention": {
            "type": "ds.chain",
            "name": "Needs attention (filtered)",
            "options": {
                "extend": "ds_all",
                "query": "| eval f_site=$f_site|s$, f_owner=$f_owner|s$, f_index=$f_index|s$, f_crit=$f_crit|s$, f_status=$f_status|s$, f_text=$f_text|s$ | `dh_ui_filter` | `dh_ui_attention(now())` | `dh_ui_headers`"
            }
        },
        "ds_opt_site": {
            "type": "ds.chain",
            "name": "site choices",
            "options": {
                "extend": "ds_all",
                "query": "| where isnotnull(site) AND site!=\"\" | stats count by site | eval label=site, value=site | table label value"
            }
        },
        "ds_opt_owner": {
            "type": "ds.chain",
            "name": "owner choices",
            "options": {
                "extend": "ds_all",
                "query": "| where isnotnull(owner) AND owner!=\"\" | stats count by owner | eval label=owner, value=owner | table label value"
            }
        },
        "ds_opt_index": {
            "type": "ds.chain",
            "name": "index choices",
            "options": {
                "extend": "ds_all",
                "query": "| where level!=\"host\" AND isnotnull(index) | stats count by index | eval label=index, value=index | table label value"
            }
        },
        "ds_banner": {
            "type": "ds.search",
            "name": "Banner",
            "options": {
                "query": "| `dh_ui_banner(dh_meta, dh_status, now())`"
            }
        },
        "ds_tamper": {
            "type": "ds.search",
            "name": "Tamper findings in 24 h (first seen)",
            "options": {
                "query": "search index=data_health source=\"dh:tamper\" sourcetype=stash earliest=-14d latest=+1d | eval it=_indextime | `dh_ui_tamper_24h(dh_status, now())`"
            }
        },
        "ds_tamper_f": {
            "type": "ds.chain",
            "name": "Tamper findings (filtered)",
            "options": {
                "extend": "ds_tamper",
                "query": "| eval f_site=$f_site|s$, f_owner=$f_owner|s$, f_index=$f_index|s$, f_crit=$f_crit|s$, f_status=$f_status|s$, f_text=$f_text|s$ | `dh_ui_filter` | table first_seen time host indicator events code detail | `dh_ui_headers`"
            }
        },
        "ds_tamper_n": {
            "type": "ds.chain",
            "name": "Tamper count (filtered)",
            "options": {
                "extend": "ds_tamper",
                "query": "| eval f_site=$f_site|s$, f_owner=$f_owner|s$, f_index=$f_index|s$, f_crit=$f_crit|s$, f_status=$f_status|s$, f_text=$f_text|s$ | `dh_ui_filter` | stats count"
            }
        },
        "ds_recovered": {
            "type": "ds.search",
            "name": "Recently recovered (24 h)",
            "options": {
                "query": "search index=data_health source=\"dh:transition\" sourcetype=stash earliest=-7d latest=+1d | `dh_ui_recovered(dh_status, now())`"
            }
        },
        "ds_recovered_f": {
            "type": "ds.chain",
            "name": "Recently recovered (filtered)",
            "options": {
                "extend": "ds_recovered",
                "query": "| eval f_site=$f_site|s$, f_owner=$f_owner|s$, f_index=$f_index|s$, f_crit=$f_crit|s$, f_status=$f_status|s$, f_text=$f_text|s$ | `dh_ui_filter` | table recovered host entity_id down_since down_for | `dh_ui_headers`"
            }
        }
    },
    "visualizations": {
        "viz_banner": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_banner"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"banner\") | lastPoint()",
                "backgroundColor": "> primary | seriesByName(\"sev\") | lastPoint() | rangeValue(sevColors)",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "context": {
                "sevColors": [
                    {
                        "to": 1,
                        "value": "#1C4F2B"
                    },
                    {
                        "from": 1,
                        "to": 3,
                        "value": "#7A5D00"
                    },
                    {
                        "from": 3,
                        "value": "#9E1C1C"
                    }
                ]
            },
            "title": "Is the data current?",
            "description": "Says whether you can trust the page right now. Green means yes. Red or amber means the statuses are held or old. Guide (project repo): docs/data-health/dashboards.md > Overview > Is the data current?"
        },
        "viz_k_tamper": {
            "type": "splunk.singlevalue",
            "title": "Tamper findings (24 h)",
            "dataSources": {
                "primary": "ds_tamper_n"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"count\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#DC4E41"
            },
            "description": "Signs that someone may have switched off logging, first seen in the last 24 hours. Findings that Ansible work explains are not counted. Guide (project repo): docs/data-health/dashboards.md > Overview > Tamper findings (24 h)"
        },
        "viz_headline": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_headline"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"headline\") | lastPoint()",
                "backgroundColor": "> primary | seriesByName(\"sev\") | lastPoint() | rangeValue(sevColors)",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "context": {
                "sevColors": [
                    {
                        "to": 1,
                        "value": "#1C4F2B"
                    },
                    {
                        "from": 1,
                        "to": 3,
                        "value": "#7A5D00"
                    },
                    {
                        "from": 3,
                        "value": "#9E1C1C"
                    }
                ]
            },
            "title": "How many hosts need attention",
            "description": "A one-line summary of the table below. Guide (project repo): docs/data-health/dashboards.md > Overview > How many hosts need attention"
        },
        "viz_attention": {
            "type": "splunk.table",
            "title": "Needs attention",
            "dataSources": {
                "primary": "ds_attention"
            },
            "options": {
                "count": 25
            },
            "description": "One row per host with late, missing or never-seen data, worst first. Read the Cause and do the Action. Click a row for Host detail. Times in the Cause use the server's time zone, not yours. Guide (project repo): docs/data-health/dashboards.md > Overview > Needs attention",
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "hl_data_health",
                        "dashboard": "dh_host",
                        "tokens": [
                            {
                                "token": "host",
                                "value": "row.Host.value"
                            }
                        ],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_recovered": {
            "type": "splunk.table",
            "title": "Recently recovered (back to OK in the last 24 h)",
            "dataSources": {
                "primary": "ds_recovered_f"
            },
            "options": {
                "count": 25
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "hl_data_health",
                        "dashboard": "dh_host",
                        "tokens": [
                            {
                                "token": "host",
                                "value": "row.Host.value"
                            }
                        ],
                        "newTab": false
                    }
                }
            ],
            "description": "Data that stopped and has come back. Click a row for Host detail. Guide (project repo): docs/data-health/dashboards.md > Overview > Recently recovered (back to OK in the last 24 h)"
        },
        "viz_tamper": {
            "type": "splunk.table",
            "title": "Tamper findings (first seen in the last 24 h)",
            "dataSources": {
                "primary": "ds_tamper_f"
            },
            "options": {
                "count": 25
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "hl_data_health",
                        "dashboard": "dh_host",
                        "tokens": [
                            {
                                "token": "host",
                                "value": "row.Host.value"
                            }
                        ],
                        "newTab": false
                    }
                }
            ],
            "description": "Signs that someone may have switched off logging. Findings that Ansible work explains are left out. Click a row for Host detail. Guide (project repo): docs/data-health/dashboards.md > Overview > Tamper findings (first seen in the last 24 h)"
        },
        "viz_k_host_expected": {
            "type": "splunk.singlevalue",
            "title": "Hosts expected",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"host_expected\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "How many hosts are on the expected list. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_host_ok": {
            "type": "splunk.singlevalue",
            "title": "Hosts OK",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"host_ok\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#53A051"
            },
            "description": "How many expected hosts are arriving on time. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_host_late": {
            "type": "splunk.singlevalue",
            "title": "Hosts late",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"host_late\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#F8BE34"
            },
            "description": "How many expected hosts are later than their limit. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_host_missing": {
            "type": "splunk.singlevalue",
            "title": "Hosts missing",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"host_missing\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#DC4E41"
            },
            "description": "How many expected hosts are silent for more than twice their limit or never arrived. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_host_muted": {
            "type": "splunk.singlevalue",
            "title": "Hosts muted",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"host_muted\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#9B9B9B"
            },
            "description": "How many expected hosts are muted on purpose. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_host_pending": {
            "type": "splunk.singlevalue",
            "title": "Hosts waiting (PENDING)",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"host_pending\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "How many expected hosts have no trusted status yet. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_sourcetype_expected": {
            "type": "splunk.singlevalue",
            "title": "Sourcetypes expected",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"sourcetype_expected\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "How many sourcetypes (per host) are on the expected list. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_sourcetype_ok": {
            "type": "splunk.singlevalue",
            "title": "Sourcetypes OK",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"sourcetype_ok\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#53A051"
            },
            "description": "How many expected sourcetypes (per host) are arriving on time. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_sourcetype_late": {
            "type": "splunk.singlevalue",
            "title": "Sourcetypes late",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"sourcetype_late\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#F8BE34"
            },
            "description": "How many expected sourcetypes (per host) are later than their limit. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_sourcetype_missing": {
            "type": "splunk.singlevalue",
            "title": "Sourcetypes missing",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"sourcetype_missing\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#DC4E41"
            },
            "description": "How many expected sourcetypes (per host) are silent for more than twice their limit or never arrived. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_sourcetype_muted": {
            "type": "splunk.singlevalue",
            "title": "Sourcetypes muted",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"sourcetype_muted\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#9B9B9B"
            },
            "description": "How many expected sourcetypes (per host) are muted on purpose. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_sourcetype_pending": {
            "type": "splunk.singlevalue",
            "title": "Sourcetypes waiting (PENDING)",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"sourcetype_pending\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "How many expected sourcetypes (per host) have no trusted status yet. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_source_expected": {
            "type": "splunk.singlevalue",
            "title": "Sources expected",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"source_expected\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "How many sources are on the expected list. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_source_ok": {
            "type": "splunk.singlevalue",
            "title": "Sources OK",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"source_ok\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#53A051"
            },
            "description": "How many expected sources are arriving on time. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_source_late": {
            "type": "splunk.singlevalue",
            "title": "Sources late",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"source_late\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#F8BE34"
            },
            "description": "How many expected sources are later than their limit. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_source_missing": {
            "type": "splunk.singlevalue",
            "title": "Sources missing",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"source_missing\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#DC4E41"
            },
            "description": "How many expected sources are silent for more than twice their limit or never arrived. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_source_muted": {
            "type": "splunk.singlevalue",
            "title": "Sources muted",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"source_muted\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "majorColor": "#9B9B9B"
            },
            "description": "How many expected sources are muted on purpose. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        },
        "viz_k_source_pending": {
            "type": "splunk.singlevalue",
            "title": "Sources waiting (PENDING)",
            "dataSources": {
                "primary": "ds_kpi"
            },
            "options": {
                "majorValue": "> primary | seriesByName(\"source_pending\") | lastPoint()",
                "sparklineDisplay": "off",
                "trendDisplay": "off"
            },
            "description": "How many expected sources have no trusted status yet. Guide (project repo): docs/data-health/dashboards.md > Overview > KPI tiles"
        }
    },
